using System.Numerics;
using AllTheModium.Client;
void Check(bool condition,string name){if(!condition)throw new Exception(name);Console.WriteLine("PASS "+name);}
Check(SwordGuardRules.CanRaise(true,true,true,false),"hold right while idle raises guard");
Check(!SwordGuardRules.CanRaise(true,true,false,false),"release right removes guard");
Check(!SwordGuardRules.CanRaise(true,true,true,true),"left attack takes priority over guard");
Check(!SwordGuardRules.CanRaise(true,false,true,false),"drawing, attacking and stowing cannot guard");
Check(!SwordGuardRules.CanRaise(false,true,true,false),"inventory, death and unfocused input cannot guard");
Check(SwordGuardRules.Frontal(Vector3.UnitZ,-Vector3.UnitZ*20),"incoming frontal hit uses inverse travel direction");
Check(!SwordGuardRules.Frontal(Vector3.UnitZ,Vector3.UnitZ),"rear hit bypasses guard");
Check(!SwordGuardRules.Frontal(Vector3.UnitZ,Vector3.UnitX),"side hit bypasses guard");
Check(!SwordGuardRules.Frontal(Vector3.UnitZ,Vector3.Zero),"missing source direction does not grant protection");
Check(!SwordGuardRules.Frontal(Vector3.UnitZ,new(float.NaN,0,0)),"invalid direction does not grant protection");
Check(SwordGuardRules.Frontal(Vector3.UnitX,-Vector3.UnitX),"protection follows the player's facing");
Check(SwordGuardRules.Damage(80,true,true,false,true)==40,"frontal bullet or melee loses half its health damage");
Check(SwordGuardRules.Damage(80,true,true,true,true)==80,"propagated body damage is not reduced twice");
Check(SwordGuardRules.Damage(80,true,false,false,true)==80,"bleeding, falls and explosions bypass guard");
Check(SwordGuardRules.Damage(80,false,true,false,true)==80,"unheld guard provides no reduction");
Check(SwordGuardRules.Damage(80,true,true,false,false)==80,"rear damage remains full strength");
Check(SwordGuardRules.Damage(0,true,true,false,true)==0,"zero damage stays zero");
Check(SwordGuardRules.Damage(-5,true,true,false,true)==-5,"non-positive amount remains unchanged");
Check(float.IsPositiveInfinity(SwordGuardRules.Damage(float.PositiveInfinity,true,true,false,true)),"non-finite amount is not rewritten");
Check(SwordGuardRules.Eligible(true,false,true),"bullet blocking enabled");
Check(!SwordGuardRules.Eligible(true,false,false),"bullet blocking disabled leaves bullets unchanged");
Check(SwordGuardRules.Eligible(false,true,false),"bullet setting leaves melee protection available");
Check(!SwordGuardRules.Eligible(false,false,true),"other damage types bypass guard");
Check(SwordGuardRules.Damage(80,true,true,false,true,0)==80,"zero percent disables reduction");
Check(SwordGuardRules.Damage(80,true,true,false,true,100)==0,"full reduction blocks eligible health damage");
Check(SwordGuardRules.Damage(80,true,true,false,true,25)==60,"custom reduction applies percentage");
Check(SwordGuardRules.Damage(80,true,true,false,true,float.NaN)==80,"invalid reduction cannot corrupt health");
var blade=SwordGuardRules.GuardBlade(Vector3.UnitX,Vector3.UnitY);
Check(SwordAppearanceRules.Scale(0,SwordAppearanceRules.Brightness(200))==0,"black source pixels remain black even at maximum brightness");
Check(SwordAppearanceRules.Scale(53,SwordAppearanceRules.Brightness(100))==53,"default brightness preserves original dark matter gray");
Check(SwordAppearanceRules.Scale(53,SwordAppearanceRules.Brightness(50))==26,"lower brightness darkens original pixels");
Check(SwordAppearanceRules.Scale(235,SwordAppearanceRules.Brightness(200))==255,"bright colors saturate without byte overflow");
Check(SwordAppearanceRules.Scale(255,SwordAppearanceRules.Opacity(0))==0,"zero opacity makes geometry invisible");
Check(SwordAppearanceRules.Scale(255,SwordAppearanceRules.Opacity(50))==128,"partial opacity reaches alpha channel");
Check(SwordAppearanceRules.Scale(0,SwordAppearanceRules.Opacity(100))==0,"source transparent pixels remain transparent");
Check(SwordAppearanceRules.Brightness(float.NaN)==1&&SwordAppearanceRules.Opacity(float.PositiveInfinity)==1,"invalid appearance settings fall back to source colors");
Check(SwordAppearanceRules.Brightness(-1)==0&&SwordAppearanceRules.Opacity(200)==1,"appearance ranges are clamped");
Check(Vector3.Dot(blade,Vector3.UnitX)<0&&Vector3.Dot(blade,Vector3.UnitY)>0&&Math.Abs(blade.Length()-1)<1e-5,"guard blade points to screen upper-left");
var yaw=Quaternion.CreateFromAxisAngle(Vector3.UnitY,1.5f);
var turned=SwordGuardRules.GuardBlade(Vector3.Transform(Vector3.UnitX,yaw),Vector3.Transform(Vector3.UnitY,yaw));
Check(Vector3.Distance(turned,Vector3.Transform(blade,yaw))<1e-5,"guard direction follows the camera instead of weapon local axes");

Check(InventoryIconRules.Pixels(1)==64&&InventoryIconRules.Pixels(2)==127,"inventory sword canvas uses exactly two native cells");
Check(InventoryIconRules.Pixels(4)==253,"regression identifies the stale four-cell native canvas");
uint red=0xff0000ff,blue=0xffff0000;var diagonal=new uint[256];for(int y=2;y<14;y++){diagonal[y*16+y]=red;diagonal[y*16+y+1]=blue;}
var swordIcon=InventoryIconRules.Build(16,16,diagonal,true);
Check(swordIcon.Width==64&&swordIcon.Height==127,"sword icon dimensions match native footprint");
var colored=swordIcon.Pixels.Where(p=>p!=0).ToArray();Check(colored.Contains(red)&&colored.Contains(blue)&&colored.All(p=>p==red||p==blue),"inventory projection preserves exact source colors with no blended pixels");
var points=(from y in Enumerable.Range(0,127) from x in Enumerable.Range(0,64) where swordIcon.Pixels[y*64+x]!=0 select (X:x,Y:y)).ToArray();
Check(points.Max(p=>p.Y)-points.Min(p=>p.Y)>100&&points.Max(p=>p.X)-points.Min(p=>p.X)<20,"diagonal source sword becomes upright without stretching its axes");
Check(points.All(p=>p.X>=4&&p.X<60&&p.Y>=4&&p.Y<123),"source sword fits its two-cell canvas without edge clipping");
var square=new uint[256];for(int y=2;y<14;y++)for(int x=2;x<14;x++)square[y*16+x]=red;
var utility=InventoryIconRules.Build(16,16,square,false);var up=(from y in Enumerable.Range(0,64) from x in Enumerable.Range(0,64) where utility.Pixels[y*64+x]!=0 select (X:x,Y:y)).ToArray();
Check(utility.Width==64&&utility.Height==64&&up.Max(p=>p.X)-up.Min(p=>p.X)==up.Max(p=>p.Y)-up.Min(p=>p.Y),"square utility source remains square in one native cell");
Check(InventoryIconRules.Build(16,16,new uint[256],true).Pixels.All(p=>p==0),"empty source stays transparent without invalid scaling");
